<?php
namespace App\Services; class DocumentCalculationService { public function calculate(array $sessions):array{$out=[];$subtotal=$discount=$tax=$total='0.00';foreach($sessions as $i=>$s){$items=[];$ss='0.00';foreach($s['items']??[] as $j=>$x){$line=$this->m($this->n($x['quantity']??0)*$this->n($x['unitPrice']??0));$items[]=[...$x,'lineTotal'=>$line,'sortOrder'=>$j];$ss=$this->add($ss,$line);}$dv=$this->n($s['discountValue']??0);$da=($s['discountType']??'percentage')==='fixed'?min($dv,$this->n($ss)):$this->n($ss)*$dv/100;$ta=max(0,$this->n($ss)-$da)*$this->n($s['taxRate']??0)/100;$net=$this->add($this->sub($ss,$this->m($da)),$this->m($ta));$out[]=[...$s,'items'=>$items,'sortOrder'=>$i,'subtotal'=>$ss,'discountAmount'=>$this->m($da),'taxAmount'=>$this->m($ta),'netTotal'=>$net];$subtotal=$this->add($subtotal,$ss);$discount=$this->add($discount,$this->m($da));$tax=$this->add($tax,$this->m($ta));$total=$this->add($total,$net);}return compact('out','subtotal','discount','tax','total')+['sessions'=>$out,'discountAmount'=>$discount,'taxAmount'=>$tax,'grandTotal'=>$total];}private function n($v):float{return (float)$v;}private function m(float $v):string{return number_format(round($v,2,PHP_ROUND_HALF_UP),2,'.','');}private function add(string $a,string $b):string{return $this->m($this->n($a)+$this->n($b));}private function sub(string $a,string $b):string{return $this->m($this->n($a)-$this->n($b));}}
